mapper.update:
UPDATE ai_capability_invocation_log
SET result_status = #{log.resultStatus},
    result_code = #{log.resultCode},
    error_code = #{log.errorCode},
    failure_stage = #{log.failureStage},
    error_message = #{log.errorMessage},
    schema_path = #{log.schemaPath},
    trace_id = #{log.traceId},
    duration_ms = #{log.durationMs},
    update_by = COALESCE(#{log.updateBy}, update_by),
    update_time = COALESCE(#{log.updateTime}, NOW())
WHERE tenant_id = #{log.tenantId}
  AND request_id = #{log.requestId}
  AND client_id = #{log.clientId}
  AND client_code = #{log.clientCode}
  AND capability_id = #{log.capabilityId}
  AND capability_code = #{log.capabilityCode}
  AND actor_type = #{log.actorType}
  AND actor_user_id = #{log.actorUserId}

  AND (service_user_id = #{log.serviceUserId}
       OR (service_user_id IS NULL AND #{log.serviceUserId} IS NULL))
  AND active_org_id = #{log.activeOrgId}
  AND del_flag = 0

mapper.select:
SELECT 

WHERE log.tenant_id = #{tenantId}
  AND log.del_flag = 0
AND log.client_id = #{clientId}

    AND log.request_id LIKE CONCAT('%', #{requestId}, '%')


    AND log.capability_code = #{capabilityCode}


    AND (log.capability_code LIKE CONCAT('%', #{capabilityKeyword}, '%')
         OR capability.capability_name LIKE CONCAT('%', #{capabilityKeyword}, '%'))


    AND (
        log.actor_user_id = #{actorUserId} OR
        actor.username LIKE CONCAT('%', #{actorKeyword}, '%')
        OR actor.real_name LIKE CONCAT('%', #{actorKeyword}, '%')
    )

AND log.result_code = #{resultCode}
ORDER BY log.create_time DESC, log.id DESC

SELECT 

WHERE log.tenant_id = #{tenantId}
  AND log.id = #{id}
  AND log.del_flag = 0
LIMIT 1
